 if(entity==="combo_preview"){const comboId=n(url.searchParams.get("comboId")),quantity=n(url.searchParams.get("quantity"));const result=await db().batch([db().prepare("SELECT cb.code,cb.name product,cri.quantity*? required,p.current_stock available,p.estimated_cost_cents,ROUND(cri.quantity*?*p.estimated_cost_cents) subtotal_cents FROM combo_recipe_items cri JOIN products p ON p.id=cri.component_product_id JOIN code_base cb ON cb.id=p.code_base_id WHERE cri.combo_id=?").bind(quantity,quantity,comboId),db().prepare("SELECT cb.code,cb.name material,cmi.quantity*? required,rm.current_stock available,rm.unit,rm.current_cost_cents,ROUND(cmi.quantity*?*rm.current_cost_cents) subtotal_cents FROM combo_material_items cmi JOIN raw_materials rm ON rm.id=cmi.material_id JOIN code_base cb ON cb.id=rm.code_base_id WHERE cmi.combo_id=?").bind(quantity,quantity,comboId)]),items=result[0].results as NRow[],materialItems=result[1].results as NRow[],all=[...items,...materialItems];return ok({items,materials:materialItems,totalCostCents:all.reduce((a,x)=>a+n(x.subtotal_cents),0),canAssemble:all.length>0&&all.every(x=>n(x.available)>=n(x.required))})}
